import { createSignal } from "solid-js";
export function Counter() {
  const [count] = createSignal(0);
  const value = count();
  return <p>{value}</p>;
}

import { createSignal } from "solid-js";
export function TodoLabel() {
  const [title] = createSignal("buy milk");
  const prefix = "Todo: ";
  const text = prefix + title();
  return <label>{text}</label>;
}

import { createSignal } from "solid-js";
export function TodoStatus() {
  const [done] = createSignal(false);
  const label = done() ? "done" : "open";
  return <span>{label}</span>;
}

import { createSignal, createEffect } from "solid-js";
export function Counter() {
  const [count] = createSignal(0);
  createEffect(() => count());
  return <p>{count()}</p>;
}

import { createMemo } from "solid-js";
import { render } from "@solidjs/web";
function App() {
  const count = createMemo(async () => 1);
  return <p>{count()}</p>;
}
render(App, document.body);

import { createMemo } from "solid-js";
import { render } from "@solidjs/web";
function TodoCount(props: { count: number }) {
  return <p>{props.count}</p>;
}
export function App() {
  const count = createMemo(async () => 1);
  return <TodoCount count={count()} />;
}
render(App, document.body);

import { createSignal } from "solid-js";
export function Counter() {
  const [count] = createSignal(0);
  const label = <p>{count()}</p>;
  return <div>{label}</div>;
}

import { createSignal, createMemo } from "solid-js";
export function Counter() {
  const [count, setCount] = createSignal(0);
  const twice = createMemo(() => {
    setCount(1);
    return count() * 2;
  });
  return <p>{twice()}</p>;
}

import { createSignal } from "solid-js";
export function Counter() {
  return <p>{createSignal(1)[0]()}</p>;
}

import { createContext, useContext } from "solid-js";
import { render } from "@solidjs/web";
const Identity = createContext<string>();
function App() {
  const name = useContext(Identity);
  return <p>{name}</p>;
}
render(App, document.body);

import { createSignal } from "solid-js";
export function Counter() {
  const [count, setCount] = createSignal(0);
  const add = () => {
    const [step] = createSignal(1);
    setCount(count() + step());
  };
  return <button onClick={add}>{count()}</button>;
}

import { createEffect, createSignal } from "solid-js";
export function Mirror() {
  const [count, setCount] = createSignal(0);
  createEffect(
    () => count(),
    value => {
      const [copy] = createSignal(value);
      console.log(copy());
    }
  );
  return <button onClick={() => setCount(count() + 1)}>{count()}</button>;
}

import { createSignal, Show } from "solid-js";
export function Banner() {
  const [count, setCount] = createSignal(1);
  return (
    <Show when={(setCount(2), count() > 0)}>
      <p>shown</p>
    </Show>
  );
}

import { createMemo, createSignal, For } from "solid-js";
export function Names() {
  const [names] = createSignal(["a", "b"]);
  return (
    <ul>
      <For each={createMemo(() => names().slice())()}>{name => <li>{name}</li>}</For>
    </ul>
  );
}

import { createSignal } from "solid-js";
function Label(props: { value: number }) {
  return <p>{props.value}</p>;
}
export function Counter() {
  const [count, setCount] = createSignal(1);
  return <Label value={(setCount(2), count())} />;
}

import { createMemo, createSignal, Errored } from "solid-js";
const money = (n: number) => "$" + n;
export function Price() {
  const [cents] = createSignal(100);
  return (
    <Errored fallback={<p>error</p>}>
      <p>{money(createMemo(() => cents() / 100)())}</p>
    </Errored>
  );
}

import { createMemo, createEffect } from "solid-js";
export function App() {
  const id = createMemo(async () => 1);
  const name = createMemo(async () => "x");
  createEffect(
    () => id(),
    value => console.log(value, name())
  );
  return <p>x</p>;
}

import { createSignal } from "solid-js";
export function App() {
  const [n, setN] = createSignal(1);
  setN(2);
  return <p>{n()}</p>;
}

import { createSignal } from "solid-js";
export function App() {
  const [text, setText] = createSignal("");
  const attrs = { onClick: async () => setText(await (await fetch("/x")).text()) };
  return <button {...attrs}>{text()}</button>;
}
